node -e '
import("./src/plan.js").then(({buildPlan,PlanError})=>{
const show=(label,fn)=>{try{console.log(label,JSON.stringify(fn()))}catch(e){console.log(label,e.code,JSON.stringify(e.cycle??e.id??e.index??null),e.name)}};
show("empty",()=>buildPlan([]));
show("notarray",()=>buildPlan({}));
show("badtask",()=>buildPlan([null]));
show("noid",()=>buildPlan([{id:""}]));
show("dupdeps",()=>buildPlan([{id:"a"},{id:"b",deps:["a","a"]}]));
show("invaliddeps",()=>buildPlan([{id:"a",deps:"x"}]));
show("unknowndep",()=>buildPlan([{id:"a"},{id:"b",deps:["missing"]}]));
show("cycleplusdependent",()=>buildPlan([{id:"a",deps:["b"]},{id:"b",deps:["a"]},{id:"z",deps:["a"]},{id:"free"}]));
});'

